insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0003-0000-4000-8000-000000000016', 'en', null, 'Business Law & Ethics', 'A working tour of the law that shapes everyday business decisions -- sources of law, ethics and social responsibility, contracts, torts, business forms, employment, intellectual property, consumer and antitrust rules, and cross-border commerce. Structure adapted from OpenStax Business Law I Essentials (CC BY 4.0).', null, 'career', 22, true, 'business', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0003-0000-4000-8000-000000000016', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"In the United States, the main sources of law include constitutions, statutes, regulations, and...","options":["only the opinions of law professors","case law made by judges (common law)","corporate policy manuals","international treaties only"],"answer":1,"explanation":"Judge-made case law, or common law, is a core source alongside constitutions, statutes, and agency regulations -- see ''The legal environment and sources of law.''"},{"prompt":"A valid contract generally requires an offer, acceptance, consideration, and...","options":["a notarized signature in every case","capacity and a lawful purpose","a lawyer present at signing","payment in cash"],"answer":1,"explanation":"Beyond offer, acceptance, and consideration, the parties must have capacity and the deal must be for a lawful purpose."},{"prompt":"A tort is best described as...","options":["a breach of a written contract","a crime prosecuted by the state","a civil wrong causing harm, for which the law allows a remedy","a type of tax"],"answer":2,"explanation":"A tort is a civil wrong (such as negligence) that harms someone and lets the injured party seek damages."},{"prompt":"Which business form gives owners limited liability while allowing pass-through taxation?","options":["sole proprietorship","general partnership","limited liability company (LLC)","unincorporated club"],"answer":2,"explanation":"An LLC combines limited liability for its members with pass-through taxation -- see ''Forms of business organization.''"},{"prompt":"A trademark primarily protects...","options":["a new invention or process","a brand name, logo, or slogan that identifies a source of goods","the expression in a book or song","a secret formula kept confidential"],"answer":1,"explanation":"Trademarks protect source identifiers like names and logos; patents cover inventions, copyrights cover expression, and trade secrets cover confidential information."},{"prompt":"In agency law, a person who acts on behalf of another is the...","options":["principal","agent","trustee","beneficiary"],"answer":1,"explanation":"The agent acts for, and can bind, the principal within the scope of authority granted."},{"prompt":"Antitrust law is mainly concerned with...","options":["protecting competition in the marketplace","setting income tax rates","registering trademarks","licensing drivers"],"answer":0,"explanation":"Antitrust law targets practices that unreasonably restrain trade or create monopolies, keeping markets competitive."},{"prompt":"An ethical framework that judges an action by its consequences for overall well-being is...","options":["deontology (duty-based ethics)","utilitarianism","virtue ethics","legal positivism"],"answer":1,"explanation":"Utilitarianism weighs outcomes and aims for the greatest good; duty and virtue ethics focus on rules and character instead -- see ''Business ethics frameworks.''"}]}'::jsonb, null, 10),
  (2, 'The legal environment and sources of law', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the main sources of law, tell civil law apart from criminal law, and explain what courts and jurisdiction mean for a business. Warm-up: from the diagnostic, which source of law is made by judges deciding cases rather than by a legislature?"},{"heading":"The idea","text":"Law in a business context comes from several layers that fit together. Constitutions set the framework and limit government power. Statutes are written laws passed by legislatures. Regulations are detailed rules issued by administrative agencies under authority a statute gives them. Common law is the body of principles built up from judges'' written decisions, where past rulings (precedent) guide future ones. These sources form a hierarchy: a regulation cannot override its statute, and no ordinary law can violate the constitution. Two big divisions matter. Criminal law involves wrongs against society, prosecuted by the government, with penalties like fines or imprisonment. Civil law resolves disputes between private parties -- for example contracts and torts -- usually seeking money damages or an order to do or stop something. Jurisdiction is a court''s power to hear a case and bind the parties, which depends on where events happened and who is involved. Remember: this is general education about how the system works, not advice about any particular matter."},{"heading":"How it plays out","text":"A city passes an ordinance (a local statute) requiring food trucks to carry insurance. A state agency issues regulations spelling out minimum coverage. A truck owner who ignores the rule may face a civil fine. Separately, if a customer is burned by spilled coffee and sues, that is a civil tort claim, not a crime. If the same owner deliberately falsified a safety inspection, the state might bring a criminal charge. One incident can raise criminal and civil questions at once, handled in different tracks with different standards of proof."},{"heading":"Your turn","text":"1) Which source of law is built from judges'' past decisions? 2) A legislature passes a written law -- what is it called? 3) Is a lawsuit between two companies over a broken deal civil or criminal? 4) Can a regulation lawfully contradict the statute that authorized it? 5) What is a court''s power to hear a case and bind the parties called? Answers: 1) Common law (precedent). 2) A statute. 3) Civil. 4) No -- a regulation must stay within the authority of its statute. 5) Jurisdiction."},{"heading":"Common mistakes and exit ticket","text":"Mistake: assuming every legal problem is criminal -- most business disputes are civil. Mistake: treating an agency regulation as outranking the statute behind it. Exit: (a) Name three sources of law. (b) What is the key difference between criminal and civil cases? Answers: any three of constitutions, statutes, regulations, common law; criminal law punishes wrongs against society and is brought by the government, while civil law resolves private disputes, usually for damages or orders."}]}'::jsonb, 'This course teaches general legal concepts for business decision-making; it is educational material, not legal advice. For a specific situation, consult a licensed attorney in the relevant jurisdiction.', 13),
  (3, 'Business ethics frameworks and corporate social responsibility', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Apply three classic ethical frameworks to a business choice and explain corporate social responsibility and the stakeholder view. Warm-up: which framework judges an action mainly by its consequences?"},{"heading":"The idea","text":"Ethics asks what a business ought to do, which is broader than what the law forces it to do. Three frameworks recur. Utilitarianism (a consequences-based view) judges an action by whether it produces the greatest overall well-being, weighing benefits and harms across everyone affected. Deontology (a duty-based view) judges an action by whether it respects moral rules and duties, such as honesty and keeping promises, regardless of the outcome. Virtue ethics asks what a person of good character -- honest, fair, courageous -- would do. Corporate social responsibility (CSR) is the idea that a business should consider its impact on society and the environment, not only its profits. The stakeholder view widens the lens beyond shareholders to include employees, customers, suppliers, communities, and the environment. A useful contrast is the shareholder view, which holds that a firm''s main duty is to maximize returns to owners within the rules. Real decisions often blend these lenses."},{"heading":"How it plays out","text":"A clothing brand learns a supplier pays below a living wage but breaks no local law. A utilitarian asks which choice yields the best overall outcome for workers, customers, and owners. A deontologist asks whether staying silent breaks a duty of honesty or fairness. A virtue lens asks what an honest, responsible company would do. Under CSR and a stakeholder view, the brand might audit suppliers and publish standards, accepting some cost for long-term trust. None of this is legally required here, which is exactly why ethics, not just law, drives the call."},{"heading":"Your turn","text":"1) Which framework focuses on duties and rules rather than results? 2) Which framework asks what a person of good character would do? 3) Name two stakeholders besides shareholders. 4) True or false: if something is legal, it must be ethical. 5) What does CSR stand for? Answers: 1) Deontology (duty-based ethics). 2) Virtue ethics. 3) Any two of employees, customers, suppliers, communities, the environment. 4) False -- legal and ethical can diverge. 5) Corporate social responsibility."},{"heading":"Common mistakes and exit ticket","text":"Mistake: collapsing ethics into legality, so anything permitted is treated as fine. Mistake: assuming utilitarianism ignores harms -- it counts them, then compares totals. Exit: (a) Contrast the shareholder and stakeholder views in one sentence. (b) Which framework is consequence-based? Answers: the shareholder view centers returns to owners within the rules, while the stakeholder view weighs the interests of everyone affected; utilitarianism is the consequence-based framework."}]}'::jsonb, 'Legal and ethical are not the same: an act can be legal yet unethical, or ethical yet against a rule. Businesses weigh both. This lesson is general education, not legal advice.', 13),
  (4, 'Contracts: formation, terms, breach, and remedies', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Identify the elements that form a contract, read basic terms, spot a breach, and match a breach to a remedy. Warm-up: besides offer and acceptance, what must each side exchange for a contract to be enforceable?"},{"heading":"The idea","text":"A contract is a legally enforceable agreement. Formation classically needs four things: an offer, acceptance of that offer, consideration (each side gives or promises something of value), and capacity plus a lawful purpose. Terms are the contract''s promises; the key ones are material terms because breaking them goes to the heart of the deal. A breach is a failure to perform a duty the contract requires. Breaches range from minor (a small, fixable shortfall) to material (a serious failure that defeats the purpose). When a breach occurs, the law supplies remedies. The usual remedy is money damages, most often compensatory damages that put the injured party where performance would have. Where money is inadequate -- say, for a unique item like land -- a court may order specific performance, directing the party to actually do what was promised. Some contracts must be in writing to be enforceable under the Statute of Frauds, such as deals involving land or that cannot be completed within one year."},{"heading":"Worked examples","text":"A bakery offers to sell 200 custom cupcakes for 400 dollars; the client accepts and pays a deposit -- offer, acceptance, and consideration are present. If the bakery delivers 200 cupcakes but two hours late with no real harm, that is a minor breach; the client still owes payment, perhaps minus a small offset. If the bakery delivers nothing, that is a material breach, and the client can seek compensatory damages: the extra cost of buying equivalent cupcakes elsewhere. Now suppose a contract to buy a specific historic building falls through; because the property is unique, a court may order specific performance rather than mere damages."},{"heading":"Your turn","text":"1) List the four classic elements of a contract. 2) A serious failure that defeats the deal''s purpose is a what kind of breach? 3) Which remedy makes a party actually perform, used for unique items? 4) What damages aim to give the injured party the benefit of the bargain? 5) Name one type of contract that must be in writing. Answers: 1) Offer, acceptance, consideration, and capacity plus lawful purpose. 2) A material breach. 3) Specific performance. 4) Compensatory damages. 5) A contract for the sale of land (or one that cannot be performed within a year), under the Statute of Frauds."},{"heading":"Common mistakes and exit ticket","text":"Mistake: thinking a promise to give a free gift is an enforceable contract -- without consideration on both sides, it usually is not. Mistake: assuming every breach lets you walk away; a minor breach usually still requires you to perform and pay, minus any offset. Exit: (a) What is consideration? (b) When is specific performance appropriate? Answers: consideration is the value each side gives or promises; specific performance fits when money damages are inadequate, typically for unique goods or property."}]}'::jsonb, 'Consideration means each side gives something of value; a bare promise to make a gift is usually not an enforceable contract. Educational overview only, not legal advice.', 15),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Which of these is a source of law built from judges'' past decisions?","options":["a statute","a regulation","common law","a constitution"],"answer":2,"explanation":"Common law is developed through judicial precedent, case by case."},{"prompt":"A dispute between two businesses over a broken contract is handled as...","options":["a criminal case brought by the state","a civil case between private parties","an administrative license renewal","a constitutional amendment"],"answer":1,"explanation":"Contract disputes are civil matters between private parties, usually seeking damages."},{"prompt":"The ethical framework that judges actions by their overall consequences is...","options":["deontology","virtue ethics","utilitarianism","legal positivism"],"answer":2,"explanation":"Utilitarianism weighs benefits and harms to find the greatest overall good."},{"prompt":"The stakeholder view of a business says managers should consider...","options":["only shareholders","only customers","everyone materially affected, such as employees, customers, and communities","only government regulators"],"answer":2,"explanation":"The stakeholder view broadens duties beyond owners to all who are affected by the firm."},{"prompt":"Which element is required to form a contract?","options":["a notary in every case","consideration on both sides","a lawyer present at signing","payment in cash only"],"answer":1,"explanation":"Each side must give something of value; consideration is essential to a binding contract."},{"prompt":"A court orders a seller to actually transfer a one-of-a-kind painting rather than pay damages. This remedy is...","options":["compensatory damages","specific performance","a criminal fine","rescission for fraud"],"answer":1,"explanation":"Specific performance is used when money is inadequate, as with unique goods."}]}'::jsonb, null, 8),
  (6, 'Torts and product liability in business', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Define a tort, list the elements of negligence, and explain how product liability can hold a maker responsible for a defective product. Warm-up: can a business be liable for harm even when nobody meant to cause it?"},{"heading":"The idea","text":"A tort is a civil wrong that causes harm and gives the injured person a right to a remedy, usually damages. Torts come in three broad kinds. Intentional torts involve deliberate acts, such as fraud or defamation. Negligence involves carelessness and is the most common business tort. Strict liability imposes responsibility without fault in certain situations. Negligence has four elements: duty (a legal obligation to use reasonable care), breach (falling below that standard), causation (the breach actually caused the harm), and damages (real injury or loss). If any element is missing, the negligence claim fails. Product liability is the area holding manufacturers and sellers responsible for injuries from defective products. Defects fall into three types: a manufacturing defect (something went wrong in making one item), a design defect (the whole design is unreasonably dangerous), and a failure to warn (inadequate instructions or warnings about a risk). Many product-liability claims use strict liability, so an injured user need not prove carelessness, only that the product was defective and caused harm."},{"heading":"How it plays out","text":"A store mops a floor but posts no wet-floor sign; a shopper slips and breaks a wrist. Negligence analysis: the store owed a duty of reasonable care, breached it by not warning, that breach caused the fall, and there are real damages -- all four elements present. Now a blender ships with a blade that can crack and fly loose. If the cracking comes from a flaw in one unit, that is a manufacturing defect; if every unit shares an unreasonably dangerous blade design, that is a design defect; if the blender is fine but the manual omits a needed warning, that is failure to warn. Under strict product liability, the injured buyer need not show the maker was careless, only that the product was defective and caused the injury."},{"heading":"Your turn","text":"1) List the four elements of negligence. 2) Which tort category covers deliberate acts like fraud? 3) Name the three types of product defect. 4) Under strict product liability, must the injured user prove the maker was careless? 5) A company posts no warning on a slippery floor and someone is hurt -- which element supplies the injury requirement? Answers: 1) Duty, breach, causation, and damages. 2) Intentional torts. 3) Manufacturing defect, design defect, and failure to warn. 4) No -- only that the product was defective and caused harm. 5) Damages."},{"heading":"Common mistakes and exit ticket","text":"Mistake: believing liability always requires intent -- negligence and strict liability do not. Mistake: forgetting causation, so a careless act with no resulting harm still is not actionable negligence. Exit: (a) What are the four elements of negligence? (b) Name one product-defect type. Answers: duty, breach, causation, damages; any of manufacturing defect, design defect, or failure to warn."}]}'::jsonb, 'Negligence turns on a duty of reasonable care; you can be liable without any intent to harm. General education, not legal advice.', 14),
  (7, 'Forms of business organization', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compare the sole proprietorship, partnership, LLC, and corporation on liability, taxation, and control. Warm-up: which simple form leaves the owner personally on the hook for all business debts?"},{"heading":"The idea","text":"Choosing a business form sets who bears liability, how profits are taxed, and who controls decisions. A sole proprietorship is one owner with no separate legal entity: easy to start, but the owner has unlimited personal liability and reports profit on a personal tax return. A general partnership is two or more owners sharing profits and management; partners typically have unlimited personal liability, and the partnership itself passes income through to the partners (pass-through taxation). A limited liability company (LLC) is a separate entity giving its members limited liability -- personal assets are generally protected -- while usually keeping pass-through taxation, blending protection with flexibility. A corporation is a separate legal person owned by shareholders, run by a board of directors, and managed by officers. It offers the strongest limited liability, but a traditional C corporation faces double taxation: the company pays tax on profits and shareholders pay again on dividends. Corporations can raise capital by selling stock, which the simpler forms cannot do as easily."},{"heading":"How it plays out","text":"A freelance designer working alone is a sole proprietor by default: no filing needed, but a lawsuit could reach personal savings. Two friends opening a cafe together, sharing everything, form a general partnership -- and each can be personally liable for the whole debt. As the cafe grows, they convert to an LLC so that a slip-and-fall claim reaches business assets but generally not their homes, while profits still flow through to their personal returns. A startup planning to raise money from investors incorporates, gaining strong liability protection and the ability to issue shares, at the cost of more formalities and potential double taxation."},{"heading":"Your turn","text":"1) Which form has one owner and unlimited personal liability by default? 2) Which entity gives members limited liability and usually pass-through taxation? 3) Who owns a corporation, and who runs it day to day? 4) What is double taxation? 5) Which form most easily raises money by selling stock? Answers: 1) The sole proprietorship. 2) The LLC. 3) Shareholders own it; a board of directors and officers run it. 4) The corporation pays tax on profits and shareholders pay tax again on dividends. 5) The corporation."},{"heading":"Common mistakes and exit ticket","text":"Mistake: assuming a partnership shields personal assets -- in a general partnership it usually does not. Mistake: thinking every corporation is double-taxed; some elect pass-through status, but the classic C corporation is taxed twice. Exit: (a) Which two forms offer limited liability? (b) Which default form needs no formation filing? Answers: the LLC and the corporation; the sole proprietorship."}]}'::jsonb, 'Limited liability shields owners'' personal assets from most business debts; it does not shield the business itself. Educational overview, not legal advice.', 14),
  (8, 'Agency and employment law basics', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain the principal-agent relationship, the idea of scope of authority, and a few core employment-law concepts. Warm-up: if a store clerk makes a sale, who is legally bound to honor it -- the clerk or the store?"},{"heading":"The idea","text":"Agency is the relationship in which one person, the agent, acts on behalf of another, the principal. Within the scope of authority the principal grants, the agent''s acts bind the principal -- that is how companies operate through employees. Authority can be actual (expressly or impliedly given) or apparent (where the principal''s conduct leads a third party to reasonably believe authority exists). Agents owe fiduciary duties to the principal, chiefly loyalty and care, meaning they must act in the principal''s interest and not secretly for themselves. Employment law governs the employer-employee relationship. A key distinction is employee versus independent contractor, which affects taxes, benefits, and liability. Many jobs are at-will, meaning either side can end the relationship at any time for any lawful reason -- but not for an illegal reason. Anti-discrimination law forbids adverse treatment based on protected characteristics such as race, sex, religion, national origin, age, and disability. Wage-and-hour rules set minimum standards like minimum wage and overtime."},{"heading":"How it plays out","text":"A sales associate quotes a price and closes a deal; because the associate acts within apparent authority, the company -- the principal -- is bound, even though the owner never spoke to the customer. If that same associate secretly steers customers to a side business, they breach the fiduciary duty of loyalty. On the employment side, a company that labels workers independent contractors to avoid overtime, while controlling their hours and tools like employees, may be misclassifying them. And firing an at-will employee is generally allowed, but firing them because of their religion is an illegal reason and unlawful."},{"heading":"Your turn","text":"1) In agency, who acts on behalf of whom? 2) What kind of authority arises when a principal''s conduct makes a third party reasonably believe an agent is authorized? 3) Name the two main fiduciary duties an agent owes. 4) What does at-will employment mean? 5) Give one protected characteristic under anti-discrimination law. Answers: 1) The agent acts on behalf of the principal. 2) Apparent authority. 3) Loyalty and care. 4) Either party may end the relationship at any time for any lawful reason. 5) Any of race, sex, religion, national origin, age, or disability."},{"heading":"Common mistakes and exit ticket","text":"Mistake: assuming a company is bound only by what the owner personally promised -- agents within their authority bind it too. Mistake: treating at-will as a license to fire for any reason at all; illegal reasons, like discrimination, are still forbidden. Exit: (a) Who is bound by an agent acting within authority? (b) What distinction affects taxes, benefits, and liability for a worker? Answers: the principal; employee versus independent contractor."}]}'::jsonb, 'An agent acting within the scope of authority can legally bind the principal, even to promises the principal never personally made. General education, not legal advice.', 13),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"The four elements of a negligence claim are duty, breach, causation, and...","options":["intent","damages","a written contract","a criminal charge"],"answer":1,"explanation":"Negligence requires actual harm; without damages the claim fails even if care was lacking."},{"prompt":"Under strict product liability, an injured user generally must show that the product was defective and caused harm, but need NOT show...","options":["that the product was used","that the maker was careless","that an injury occurred","that the product was sold"],"answer":1,"explanation":"Strict liability does not require proving negligence -- only a defect and resulting harm."},{"prompt":"Which business form gives its owners the strongest limited liability and can raise capital by selling stock?","options":["sole proprietorship","general partnership","corporation","unincorporated association"],"answer":2,"explanation":"The corporation offers strong limited liability and can issue shares to investors."},{"prompt":"A general partnership is characterized by...","options":["one owner and no personal liability","shared management and usually unlimited personal liability for partners","no taxation at all","ownership by shareholders"],"answer":1,"explanation":"Partners share control and typically bear unlimited personal liability, with income passing through to them."},{"prompt":"When a principal''s own conduct leads a third party to reasonably believe an agent is authorized, the agent has...","options":["no authority","apparent authority","criminal authority","fiduciary immunity"],"answer":1,"explanation":"Apparent authority arises from the principal''s conduct and can bind the principal."},{"prompt":"Firing an at-will employee is generally lawful, EXCEPT when the reason is...","options":["poor performance","a business slowdown","the employee''s religion or another protected trait","restructuring the team"],"answer":2,"explanation":"At-will allows termination for lawful reasons, but not for illegal ones like discrimination."}]}'::jsonb, null, 8),
  (10, 'Intellectual property: patents, trademarks, copyrights, trade secrets', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Match each kind of intellectual property to what it protects and how long it lasts. Warm-up: which protection covers a brand name or logo rather than an invention?"},{"heading":"The idea","text":"Intellectual property (IP) is a set of legal rights over creations of the mind. There are four main types. A patent protects a new, useful, and non-obvious invention -- a product or process -- giving the inventor an exclusive right for a limited term (commonly around twenty years for a utility patent), after which it enters the public domain. A trademark protects words, names, logos, or slogans that identify the source of goods or services; it can last indefinitely as long as it stays in use and is defended. A copyright protects original works of authorship fixed in a tangible form -- books, music, software, art -- and arises automatically upon creation, lasting a long term (generally the author''s life plus seventy years). A trade secret is confidential business information, such as a formula or method, that gives a competitive edge; it is protected as long as it stays secret and reasonable steps guard it, with no fixed expiration. Infringement is unauthorized use of protected IP, and remedies can include damages and injunctions. A single product might combine several: a branded gadget could hold a patent on its mechanism, a trademark on its name, copyright on its software, and a trade secret in its manufacturing process."},{"heading":"Worked examples","text":"A startup invents a new water-filter mechanism and files a utility patent, gaining roughly twenty years of exclusivity. It sells the filter under a catchy brand name, which it registers as a trademark that can renew indefinitely. The user manual and control software are copyrighted automatically when written. The exact chemical coating that makes the filter work, never disclosed, is kept as a trade secret and stays protected only while it remains confidential. If a rival copies the brand name to confuse buyers, that is trademark infringement; if the rival reverse-engineers and independently discovers the coating, the trade secret may simply be lost, since independent discovery is not infringement."},{"heading":"Your turn","text":"1) Which IP type protects an invention or process? 2) Which protects a brand name or logo and can last indefinitely if used? 3) Which arises automatically when an original work is fixed in tangible form? 4) Which protects confidential information with no fixed term, as long as it stays secret? 5) Is independently discovering a competitor''s secret formula generally infringement? Answers: 1) A patent. 2) A trademark. 3) A copyright. 4) A trade secret. 5) No -- independent discovery or reverse engineering generally is not trade-secret infringement."},{"heading":"Common mistakes and exit ticket","text":"Mistake: thinking you must register a copyright before it exists -- protection begins at creation, though registration adds benefits. Mistake: assuming a trademark expires on a fixed date; it can last indefinitely with continued use. Exit: (a) Which IP protects a new invention? (b) Which protects confidential information as long as it stays secret? Answers: a patent; a trade secret."}]}'::jsonb, 'Each IP type protects something different; a single product can carry several at once. General education, not legal advice.', 14),
  (11, 'Consumer protection and antitrust basics', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what consumer protection law targets and describe core antitrust concerns like monopolization and price fixing. Warm-up: is antitrust law meant to protect competitors or the process of competition itself?"},{"heading":"The idea","text":"Consumer protection law shields buyers from unfair or deceptive business practices. It targets false advertising (misleading claims about a product), fraud, unfair terms, and unsafe products, and it supports rights like accurate labeling and truthful pricing. Agencies enforce these rules and can order companies to stop and to compensate consumers. Antitrust law protects competition in the marketplace so that prices, quality, and innovation are set by rivalry rather than by manipulation. Its main concerns include monopolization (using improper means to gain or keep dominant market power), price fixing (competitors secretly agreeing on prices instead of competing), bid rigging, and market division. Some conduct, like naked price fixing among competitors, is treated as automatically illegal (a per se violation); other conduct is judged under a rule of reason that weighs its actual competitive effects. Mergers that would substantially lessen competition can be blocked. The through-line is that antitrust guards the competitive process, not any single competitor, so aggressive but fair competition is allowed even when rivals lose."},{"heading":"How it plays out","text":"A supplement company advertises that its pills cure a disease with no evidence; that is deceptive advertising, and a consumer-protection agency can order it to stop and to refund buyers. Separately, three regional bakeries secretly agree to all charge the same high bread price -- classic price fixing, treated as per se illegal because it strips buyers of competition. Now a dominant software firm ties two products together and blocks rivals through improper means; that may be unlawful monopolization judged for its competitive effects. But a store that simply lowers prices and wins customers fairly is doing exactly what antitrust law wants, even though competitors are hurt."},{"heading":"Your turn","text":"1) What does consumer protection law target? 2) Name two core antitrust concerns. 3) Competitors secretly agreeing on a common price is called what? 4) Does antitrust protect individual competitors or the competitive process? 5) What is the difference between a per se violation and rule-of-reason analysis? Answers: 1) Unfair or deceptive practices, such as false advertising, fraud, and unsafe products. 2) Any two of monopolization, price fixing, bid rigging, market division. 3) Price fixing. 4) The competitive process, not individual competitors. 5) A per se violation is automatically illegal, while rule-of-reason weighs the conduct''s actual competitive effects."},{"heading":"Common mistakes and exit ticket","text":"Mistake: assuming antitrust exists to rescue struggling competitors -- it protects competition, so fair winning is fine. Mistake: thinking all antitrust conduct gets the same test; some acts are per se illegal, others use the rule of reason. Exit: (a) Give one example of a deceptive practice. (b) What is price fixing? Answers: false advertising (or fraud, or unsafe products); competitors secretly agreeing on prices rather than competing."}]}'::jsonb, 'Antitrust protects competition, not individual competitors; a firm can win by being better, just not by unfairly blocking rivals. General education, not legal advice.', 13),
  (12, 'International and e-commerce law basics', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how choice-of-law and jurisdiction work across borders and identify basic legal issues in online commerce. Warm-up: when a buyer in one country and a seller in another disagree, whose law decides the dispute?"},{"heading":"The idea","text":"International business law deals with transactions that cross national borders, where more than one country''s rules could apply. Two questions recur: choice of law (which country''s law governs the contract) and jurisdiction or forum (which country''s courts, or which arbitration body, will hear a dispute). Parties commonly answer both in advance with a choice-of-law clause and a forum-selection or arbitration clause, reducing uncertainty. Treaties and conventions can harmonize rules; for example, some sales of goods between businesses in different countries are governed by an international sales convention unless the parties opt out. Trade is also shaped by tariffs, import and export controls, and trade agreements. E-commerce law covers business conducted online. Key issues include contract formation by clickwrap and browsewrap agreements (where clicking I agree can form a binding contract), electronic signatures being legally valid, data privacy and the handling of personal information, consumer protection applied to online sellers, and the reach of a country''s law over foreign websites. Because a website can reach customers anywhere, businesses must consider the laws of the places where their customers are, not only their home country."},{"heading":"How it plays out","text":"A software company in one country licenses its product to a business in another. Their contract includes a choice-of-law clause selecting one country''s law and an arbitration clause naming a neutral forum, so a later dispute avoids a fight over whose courts apply. Online, a shopper clicks I agree to terms before checkout -- a clickwrap agreement that generally forms a binding contract, while terms merely posted in a footer (browsewrap) are weaker. The same store, selling to customers abroad, must respect data-privacy rules in those customers'' regions when it collects personal information, even though its servers sit elsewhere."},{"heading":"Your turn","text":"1) What does a choice-of-law clause decide? 2) What does a forum-selection or arbitration clause decide? 3) Which is generally stronger, clickwrap or browsewrap? 4) Name one core e-commerce legal issue besides contract formation. 5) Why might an online seller need to consider foreign laws? Answers: 1) Which country''s law governs the contract. 2) Which court or arbitration body hears a dispute. 3) Clickwrap, because the user affirmatively clicks to agree. 4) Any of electronic signatures, data privacy, online consumer protection, cross-border jurisdiction. 5) Because its website can reach customers in other countries, whose laws may apply."},{"heading":"Common mistakes and exit ticket","text":"Mistake: assuming your home country''s law automatically governs a cross-border deal -- absent a clause, it is contested. Mistake: treating a buried browsewrap notice as ironclad; affirmative clickwrap consent is far more reliable. Exit: (a) Name the two questions cross-border disputes raise about applicable rules. (b) What kind of online agreement is formed by clicking I agree? Answers: choice of law and choice of forum/jurisdiction; a clickwrap agreement."}]}'::jsonb, 'Cross-border deals raise the question of which country''s law and which forum apply; parties often decide this in advance by contract. General education, not legal advice.', 13),
  (13, 'Checkpoint 3', 'quiz', '{"questions":[{"prompt":"A patent protects an invention for a limited term, after which the invention...","options":["becomes a trade secret","enters the public domain","converts to a trademark","is destroyed"],"answer":1,"explanation":"After a utility patent''s term (commonly around twenty years), the invention is free for public use."},{"prompt":"Which intellectual property right can last indefinitely as long as it stays in use?","options":["a patent","a copyright","a trademark","none of these"],"answer":2,"explanation":"A trademark can be renewed indefinitely while it remains in use and is defended."},{"prompt":"Competitors secretly agreeing to charge the same price is an example of...","options":["fair competition","price fixing, a core antitrust violation","consumer protection","a valid contract"],"answer":1,"explanation":"Price fixing among competitors is a classic antitrust violation, often treated as per se illegal."},{"prompt":"Antitrust law is designed to protect...","options":["individual competitors from any loss","the competitive process in the market","only large corporations","government revenue"],"answer":1,"explanation":"Antitrust safeguards competition itself, so fair winning is allowed even when rivals lose."},{"prompt":"In a cross-border contract, a clause selecting which country''s law governs is a...","options":["choice-of-law clause","warranty","non-compete","copyright notice"],"answer":0,"explanation":"A choice-of-law clause specifies the governing law, reducing uncertainty in international deals."},{"prompt":"Clicking an I agree button before checkout typically forms which kind of online agreement?","options":["browsewrap","clickwrap","an oral contract","no contract at all"],"answer":1,"explanation":"Clickwrap requires an affirmative click and generally forms a binding contract."}]}'::jsonb, null, 8),
  (14, 'Capstone: applying law and ethics to a business scenario', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read a realistic business scenario, spot the legal issues across the course, and weigh an ethical response alongside the legal one. Warm-up: name three areas of law you would scan when a new product launches."},{"heading":"The scenario","text":"BrightBrew is a small LLC that sells a new cold-brew coffee maker online to customers in several countries. It sources parts from an overseas supplier, employs a few workers plus some gig delivery drivers, markets aggressively, and guards a proprietary brewing method. Just after launch, three things happen at once: a customer is burned when a unit''s heating element cracks; a competitor starts selling a nearly identical machine under a confusingly similar name; and a manager proposes quietly agreeing with two rival brands to all hold prices high for the season. BrightBrew must respond."},{"heading":"Issue spotting: the law","text":"Business form: as an LLC, BrightBrew''s members generally have limited liability, so a lawsuit reaches business assets, not their personal homes. Product liability and torts: the cracked heating element points to a possible manufacturing or design defect; under strict product liability the burned customer need not prove carelessness, only a defect that caused harm, so BrightBrew should investigate, possibly recall, and check insurance. Intellectual property: the copycat name is likely trademark infringement if it confuses buyers, and the brewing method can stay a trade secret only while kept confidential. Employment and agency: the delivery drivers raise an employee-versus-contractor classification question affecting taxes and liability, and workers acting within their authority can bind the company. International and e-commerce: selling across borders raises choice-of-law, data-privacy, and online-contract issues. Antitrust: the manager''s plan to agree with rivals on prices is price fixing, a serious per se violation. Consumer protection: marketing must avoid deceptive claims."},{"heading":"Your turn","text":"1) Does the manager''s price plan violate the law, and under which area? 2) Under strict product liability, what must the burned customer prove? 3) What legal claim fits the competitor''s confusingly similar name? 4) Which classification question do the gig drivers raise? 5) How does BrightBrew keep its brewing method legally protected? Answers: 1) Yes -- agreeing with rivals to hold prices is price fixing under antitrust law, typically per se illegal, so BrightBrew must refuse. 2) That the product was defective and the defect caused the harm, not that the maker was careless. 3) Trademark infringement. 4) Employee versus independent contractor. 5) By keeping it confidential and taking reasonable steps to guard it as a trade secret."},{"heading":"Ethics and exit ticket","text":"Beyond legality, BrightBrew faces ethical choices. A utilitarian view weighs the harm of an unsafe product against the cost of a recall and favors protecting customers. A duty-based view says honesty and care require warning buyers and refusing the price scheme regardless of profit. A stakeholder and CSR lens counsels transparency with customers, fair treatment of workers, and responsible sourcing to build long-term trust. Note that even where an action might be legally arguable, the ethical course can be clearer -- and this material is general education, not legal advice, so a real BrightBrew would consult a licensed attorney. Exit: (a) Give one legal issue and one ethical consideration in the burn incident. (b) Why must BrightBrew reject the price-fixing proposal? Answers: legally it is possible product liability for a defect, and ethically it should warn customers and prioritize safety; it must reject price fixing because agreeing with competitors on prices is an antitrust violation and unethical toward consumers."}]}'::jsonb, 'Real decisions blend several areas of law with ethics at once; spotting all the issues matters as much as any single answer. General education, not legal advice.', 15),
  (15, 'Comprehensive final quiz', 'quiz', '{"questions":[{"prompt":"Which of the following is NOT a primary source of law?","options":["a constitution","a statute","a company''s internal style guide","an agency regulation"],"answer":2,"explanation":"Internal company documents are not law; constitutions, statutes, regulations, and common law are."},{"prompt":"An action can be legal yet still be...","options":["a criminal offense","unethical","a constitutional amendment","impossible"],"answer":1,"explanation":"Law and ethics can diverge; something permitted may still be ethically wrong."},{"prompt":"Which framework judges an action by whether it respects moral duties, regardless of outcome?","options":["utilitarianism","deontology","cost-benefit analysis","market efficiency"],"answer":1,"explanation":"Deontology is duty-based and focuses on rules rather than consequences."},{"prompt":"A contract requires offer, acceptance, consideration, capacity, and a...","options":["notarized seal","lawful purpose","government permit","witness"],"answer":1,"explanation":"The agreement''s purpose must be lawful, alongside the other formation elements."},{"prompt":"A remedy that orders a party to actually perform, used when money is inadequate, is...","options":["compensatory damages","specific performance","a criminal fine","rescission"],"answer":1,"explanation":"Specific performance is granted for unique goods or property where damages fall short."},{"prompt":"The most common business tort, based on a failure to use reasonable care, is...","options":["defamation","negligence","fraud","battery"],"answer":1,"explanation":"Negligence, built on duty, breach, causation, and damages, is the most common business tort."},{"prompt":"Which business form provides limited liability while typically keeping pass-through taxation?","options":["sole proprietorship","general partnership","LLC","C corporation"],"answer":2,"explanation":"The LLC blends limited liability with pass-through taxation."},{"prompt":"In agency law, apparent authority arises from...","options":["a written contract only","the principal''s conduct leading a third party to reasonably believe authority exists","the agent''s private intentions","a court order"],"answer":1,"explanation":"Apparent authority stems from how the principal''s conduct appears to third parties."},{"prompt":"Which intellectual property protects a confidential formula with no fixed expiration, as long as secrecy is maintained?","options":["a patent","a copyright","a trademark","a trade secret"],"answer":3,"explanation":"A trade secret lasts as long as the information stays secret and is reasonably protected."},{"prompt":"Competitors secretly agreeing on prices is a violation of...","options":["copyright law","antitrust law","employment law","contract law"],"answer":1,"explanation":"Price fixing among competitors is a core antitrust violation."},{"prompt":"A clause specifying which country''s law governs an international contract is a...","options":["choice-of-law clause","warranty disclaimer","trademark registration","non-disclosure agreement"],"answer":0,"explanation":"A choice-of-law clause designates the governing law for a cross-border deal."},{"prompt":"Under strict product liability, an injured consumer must show a defect and that it caused harm, but need NOT show that...","options":["the product was used as intended","the manufacturer was careless","an injury occurred","the product was defective"],"answer":1,"explanation":"Strict liability does not require proof of negligence, only a defect that caused harm."}]}'::jsonb, null, 12)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0003-0000-4000-8000-000000000016' and l.position = v.pos
);
